// ---------- 比赛榜单回放关联 ----------

// ParseContestReplay 把回放列表原始 JSON 转换为 camelCase 视图（与 ParseContest 同一模式）
export function ParseContestReplay(item: ContestReplayRaw): ContestReplay {
  const result = {} as ContestReplay;
  result.id = item.id;
  if (item.source_contest_id !== undefined) {
    result.sourceContestId = item.source_contest_id;
  }
  result.title = item.title;
  result.enabled = item.enabled;
  if (item.source_title !== undefined) {
    result.sourceTitle = item.source_title;
  }
  result.playerCount = item.player_count || 0;
  result.isAlias = item.is_alias || false;
  result.problemMatched = item.problem_matched || false;
  return result;
}

// ParseContestReplayEligible 把可关联候选原始 JSON 转换为 camelCase 视图（与 ParseContestReplay 同一模式）
export function ParseContestReplayEligible(item: ContestReplayEligibleRaw): ContestReplayEligible {
  const result = {} as ContestReplayEligible;
  result.contestId = item.contest_id;
  result.title = item.title;
  result.startTime = new Date(item.start_time).toLocaleString();
  result.endTime = new Date(item.end_time).toLocaleString();
  result.linked = item.linked || false;
  result.canView = item.can_view !== false;
  result.isAlias = item.is_alias || false;
  // 回放比赛标识：候选源本身是回放比赛时，选择器里要标出来便于管理员辨认
  result.isReplay = item.is_replay === true;
  // 中立本体指纹：创建期可能缺省，缺省时不写字段，别名判定按「无指纹不比较」处理
  if (item.body_hash !== undefined) {
    result.bodyHash = item.body_hash;
  }
  return result;
}

