// ParseContestReplayImportPreview 把回放文件导入预览原始 JSON 转换为 camelCase 视图
export function ParseContestReplayImportPreview(item: ContestReplayImportPreviewRaw): ContestReplayImportPreview {
  return {
    previewId: item.preview_id,
    targetProblems: item.target_problems.map((p) => ({
      index: p.index,
      problemId: p.problem_id,
      title: p.title,
    })),
    sourceProblems: item.source_problems.map((p) => ({
      index: p.index,
      problemId: p.problem_id,
      title: p.title,
    })),
    problemMap: item.problem_map.map((m) => ({
      sourceIndex: m.source_index,
      targetIndex: m.target_index,
    })),
    participants: item.participants.map((p) => ({
      sourceUserId: p.source_user_id,
      username: p.username,
      nickname: p.nickname,
      email: p.email,
      problems: p.problems.map((e) => ({
        sourceIndex: e.source_index,
        status: e.status,
        acSeconds: e.ac_seconds ?? null,
        score: e.score ?? null,
        submits: e.submits,
      })),
    })),
    warnings: item.warnings ?? [],
    titleSuggestion: item.title_suggestion,
    durationSec: item.duration_sec ?? 0,
    filename: item.filename ?? "",
    // 旧后端没有这两个字段：格子数与有效选手数按 participants 兜底推算，
    // 保证前端「致命判定」在前后端版本不一致时也不会误判（无法解析格数按 0 处理）。
    unparsedCells: item.unparsed_cells ?? 0,
    scoredParticipants:
      item.scored_participants ?? item.participants.filter((p) => (p.problems?.length ?? 0) > 0).length,
  };
}

// PostContestReplayContestPreview POST /contest/replay/contest/preview：
// 新建回放比赛时上传榜单 CSV，按「将作为该回放比赛的题目」的 ID 顺序解析并生成对齐预览（不落库）。
// problems 必须按 CSV 题目列顺序传入（逗号分隔），后端据此建立源列 ↔ 题目序号的对齐。
export function PostContestReplayContestPreview(problems: number[], file: File) {
  const formData = new FormData();
  formData.append("problems", problems.join(","));
  formData.append("file", file);
  return httpRequest({
    url: "/contest/replay/contest/preview",
    method: "post",
    data: formData,
    headers: {
      "Content-Type": "multipart/form-data",
    },
    timeout: 1000 * 60 * 5,
  });
}

// PostContestReplayContestCreate POST /contest/replay/contest/create：
// 单事务创建「回放比赛」（contest + 题目 + 中立本体 + 自关联行），返回 { contest_id }。
// problems 与预览同序（后端以本次请求为准重新校验，防篡改）。
// private 决定新比赛可见性：回放榜单常含真实选手成绩，必须由创建者显式选择。
// 形参不能叫 private（严格模式保留字），这里用 isPrivate。
export function PostContestReplayContestCreate(
  title: string,
  problems: number[],
  previewId: string,
  problemMap: ContestReplayImportMapItem[],
  isPrivate: boolean
) {
  return httpRequest({
    url: "/contest/replay/contest/create",
    method: "post",
    data: {
      title: title ?? "",
      problems: problems,
      preview_id: previewId,
      private: isPrivate === true,
      problem_map: problemMap.map((m) => ({
        source_index: m.sourceIndex,
        target_index: m.targetIndex,
      })),
    },
  });
}
